use super::*;
const VOCAB:[&str;12]=["iteration","precommitment","rotation","peer_review","redundancy","signaling","resource_pooling","randomization","reciprocity","error_feedback","decomposition","other"];
fn tags(row:&Json,key:&str)->Result<BTreeSet<String>>{array(row,key)?.iter().map(|v|v.string().map(str::to_string)).collect()}
fn distance(a:&BTreeSet<String>,b:&BTreeSet<String>)->f64{let n=a.union(b).count();if n==0{0.}else{1.-a.intersection(b).count() as f64/n as f64}}
fn cross(a:&[&Json],b:&[&Json])->Result<Json>{let mut ds=vec![];for x in a{for y in b{ds.push(distance(&tags(x,"consensus")?,&tags(y,"consensus")?));}}Ok(average(&ds))}
fn within(a:&[&Json])->Result<Json>{let mut ds=vec![];for (i,x) in a.iter().enumerate(){for y in &a[..i]{ds.push(distance(&tags(x,"consensus")?,&tags(y,"consensus")?));}}Ok(average(&ds))}
pub(super) fn analyze(dir:&Path,coding:&Json)->Result<Json>{let (report,_,pack,mapping)=ratings::mapped(dir,"life")?;let mut seen=BTreeSet::new();let mut by_id:BTreeMap<String,Vec<&Json>>=BTreeMap::new();for c in coding.array()?{let id=s(c,"id")?;let rater=s(c,"rater")?;require(mapping.contains_key(id),"Unknown proposal")?;require(!rater.trim().is_empty(),"Rater ID required")?;require(seen.insert((id.to_string(),rater.to_string())),"Duplicate coding")?;require(!s(c,"mechanism_summary")?.trim().is_empty(),"Mechanism summary required")?;let ts=tags(c,"tags")?;require(!ts.is_empty()&&ts.len()==array(c,"tags")?.len(),"Unique nonempty tags required")?;require(ts.iter().all(|t|VOCAB.contains(&t.as_str())),"Use fixed vocabulary")?;by_id.entry(id.into()).or_default().push(c);}
 let mut rows=vec![];for p in &pack{let id=s(p,"id")?;let cs=by_id.get(id).ok_or("Two independent coders required")?;require(cs.len()>=2,"Two independent coders required")?;let ts=cs.iter().map(|c|tags(c,"tags")).collect::<Result<Vec<_>>>()?;let consensus=array(cs[0],"tags")?.iter().filter(|t|ts.iter().all(|s|s.contains(t.string().unwrap()))).cloned().collect::<Vec<_>>();let mut union=vec![];let mut seen=BTreeSet::new();for c in cs{for t in array(c,"tags")?{if seen.insert(t.string()?.to_owned()){union.push(t.clone());}}}let mut ds=vec![];for i in 0..ts.len(){for j in 0..i{ds.push(distance(&ts[i],&ts[j]));}}let t=&mapping[id];let mut row=obj([("id",text(id)),("task",t.get("task")?.get("id")?.clone()),("consensus",arr(consensus)),("union",arr(union)),("coder_disagreement",average(&ds)),("summaries",arr(cs.iter().map(|c|c.get("mechanism_summary").unwrap().clone())))]);for k in ["pair","branch","day","phase","condition","repeat"]{row.put(k,t.get(k)?.clone());}rows.push(row);}
 let mut groups:BTreeMap<String,Vec<&Json>>=BTreeMap::new();for r in &rows{if s(r,"phase")?=="primary"{let key=arr(["pair","day","task"].map(|k|r.get(k).unwrap().clone())).encode();groups.entry(key).or_default().push(r);}}
 let mut contrasts=vec![];for xs in groups.values(){let pick=|b:&str,c:&str|xs.iter().copied().filter(|r|s(r,"branch").ok()==Some(b)&&s(r,"condition").ok()==Some(c)).collect::<Vec<_>>();let mut conditions=BTreeMap::new();for c in ["full","replica","rag","empty"]{let a=pick("a",c);let b=pick("b",c);conditions.insert(c.to_string(),obj([("between_histories",cross(&a,&b)?),("within_a",within(&a)?),("within_b",within(&b)?)]));}contrasts.push(obj([("pair",xs[0].get("pair")?.clone()),("day",xs[0].get("day")?.clone()),("task",xs[0].get("task")?.clone()),("conditions",Json::Object(conditions)),("developmental_same_history",obj([("a",cross(&pick("a","full"),&pick("a","replica"))?),("b",cross(&pick("b","full"),&pick("b","replica"))?)]))]));}
 let pairs=rows.iter().map(|r|s(r,"pair")).collect::<Result<BTreeSet<_>>>()?.len();Ok(obj([("mock",report.get("mock")?.clone()),("independent_pairs",num(pairs as f64)),("vocabulary",arr(VOCAB.map(text))),("rows",arr(rows)),("contrasts",arr(contrasts)),("claim",text("Functional tag distance is not creativity or causal proof. Empty consensus and coder disagreement require inspection. Dates, tasks, repeats and controls are nested inside source pairs."))]))}
